/* 0070_customer_dashboard.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
create or replace function public.customer_dashboard_summary() returns table ( active_orders bigint, in_progress bigint, awaiting_content bigint, live_links bigint, live_links_this_month bigint, total_spend_minor bigint, orders_all bigint ) language sql stable security invoker set search_path = public as $$ with mine as ( select o.id, o.status, o.total_minor, o.placed_at from public.orders o where o.user_id = auth.uid() ), placements as ( select i.id, i.status, o.placed_at from public.order_items i join mine o on o.id = i.order_id ) select (select count(*) from mine where status in ('awaiting-content', 'in-progress', 'submitted')), (select count(*) from mine where status = 'in-progress'), (select count(*) from mine where status = 'awaiting-content'), (select count(*) from placements where status = 'live'), (select count(*) from placements where status = 'live' and placed_at >= date_trunc('month', timezone('utc', now()))), (select coalesce(sum(total_minor), 0) from mine where status not in ('cancelled', 'draft')), (select count(*) from mine where status <> 'draft'); $$;
comment on function public.customer_dashboard_summary() is 'The signed-in customer''s own figures. Security invoker on purpose: row level security scopes it, and a definer here would be one wrong where-clause away from one customer reading another''s spend.';
create or replace function public.customer_recommendations(p_limit integer default 4) returns table ( id uuid, personalised boolean ) language sql stable security invoker set search_path = public as $$ with mine as ( select distinct w.primary_category_id as category_id from public.order_items i join public.orders o on o.id = i.order_id join public.websites w on w.id = i.website_id where o.user_id = auth.uid() and o.status <> 'draft' and w.primary_category_id is not null ), bought as ( select distinct i.website_id from public.order_items i join public.orders o on o.id = i.order_id where o.user_id = auth.uid() ), sellable as ( select w.id, w.domain, w.domain_rating, w.primary_category_id from public.websites w where w.status = 'active' and not exists (select 1 from bought b where b.website_id = w.id) and exists ( select 1 from public.services s where s.website_id = w.id and s.available and s.price_minor > 0 ) ) select sellable.id, (select count(*) > 0 from mine) as personalised from sellable where (select count(*) from mine) = 0 or sellable.primary_category_id in (select category_id from mine) order by sellable.domain_rating desc nulls last, sellable.id asc limit greatest(1, least(coalesce(p_limit, 4), 12)); $$;
comment on function public.customer_recommendations(integer) is 'Active listings to suggest, from the categories this customer has ordered in. Returns personalised=false when they have no orders, so the caller can head the section honestly.';
